import pandas as pd
import re
from collections import defaultdict, Counter
import csv

def normalize_text(text):
    if pd.isna(text): return ""
    text = str(text).lower().strip()
    text = re.sub(r'[&\-_/]+', ' ', text)
    text = re.sub(r'\s+', ' ', text)
    return text.strip()

def parse_path(path):
    if pd.isna(path): return []
    path = str(path).strip('"').strip("'")
    levels = [level.strip() for level in path.split('>')]
    return [l for l in levels if l]

def extract_words(text):
    words = set(normalize_text(text).split())
    stop_words = {'and', 'or', 'the', 'a', 'an', 'for', 'of', 'in', 'on', 'at', 'to', 'with', 'by'}
    return words - stop_words

def word_overlap(t1, t2):
    w1, w2 = extract_words(t1), extract_words(t2)
    if not w1 or not w2: return 0.0
    return len(w1 & w2) / len(w1 | w2)

def make_name(names, max_words=4):
    word_freq = Counter()
    for name in names[:100]:
        word_freq.update(extract_words(name))
    common = [w for w, _ in word_freq.most_common(max_words) if len(w) > 2]
    if common:
        return ' | '.join(common[:max_words])
    if names:
        words = names[0].split()[:max_words]
        return ' | '.join(words)
    return 'general'

print("Loading data...")
amazon = pd.read_csv('/root/data/amazon_product_categories.csv')
amazon['source'] = 'amazon'
fb = pd.read_csv('/root/data/fb_product_categories.csv')
fb['source'] = 'facebook'
google = pd.read_csv('/root/data/google_shopping_product_categories.csv')
google['source'] = 'google'

all_data = []
for df in [amazon, fb, google]:
    src = df['source'].iloc[0]
    for _, row in df.iterrows():
        path = parse_path(row['category_path'])
        if path:
            all_data.append({'source': src, 'original': row['category_path'], 'path': path})

print(f"Total paths: {len(all_data)}")
