# Build level 1 categories
print("Building Level 1...")
level1_cats = defaultdict(lambda: {'count': 0, 'sources': set(), 'items': []})
for item in all_data:
    cat = normalize_text(item['path'][0])
    level1_cats[cat]['count'] += 1
    level1_cats[cat]['sources'].add(item['source'])
    level1_cats[cat]['items'].append(item)

# Cluster level 1 to 10-20 categories
level1_sorted = sorted(level1_cats.items(), key=lambda x: x[1]['count'], reverse=True)
level1_clusters = {}
used = set()

for i, (cat, info) in enumerate(level1_sorted):
    if i in used: continue
    cluster_items = list(info['items'])
    cluster_names = [cat]
    used.add(i)

    # Merge similar categories
    for j, (other_cat, other_info) in enumerate(level1_sorted[i+1:], start=i+1):
        if j in used or len(level1_clusters) >= 15: continue
        if word_overlap(cat, other_cat) > 0.4:
            cluster_items.extend(other_info['items'])
            cluster_names.append(other_cat)
            used.add(j)

    names = [item['path'][0] for item in cluster_items[:100]]
    l1_name = make_name(names)
    level1_clusters[l1_name] = cluster_items
    if len(level1_clusters) >= 18:
