# Add remaining to largest cluster if needed
for i, (cat, info) in enumerate(level1_sorted):
    if i not in used:
        largest = max(level1_clusters.items(), key=lambda x: len(x[1]))
        level1_clusters[largest[0]].extend(info['items'])

print(f"Level 1 categories: {len(level1_clusters)}")

# Build full taxonomy
taxonomy = {}
